export function WcagBadge({
  title = "{{title}}",
  level = "{{level}}",
  showChecklist = {{showChecklist}},
  accent = "{{accent}}",
}) {
  const fillWidth = { A: "33%", AA: "66%", AAA: "100%" }[level];
  const items = [
    { key: "a", label: "Perceivable basics met" },
    { key: "aa", label: "Enhanced contrast & resize met" },
    { key: "aaa", label: "Highest-tier support met" },
  ];
  const active = { A: ["a"], AA: ["a", "aa"], AAA: ["a", "aa", "aaa"] }[level];
  return (
    <div style={{ width: 300, fontFamily: "system-ui, sans-serif", fontSize: 14, color: "#241430" }}>
      <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between" }}>
        <p style={{ margin: 0, fontWeight: 700 }}>{title}</p>
        <span style={{ padding: "3px 10px", borderRadius: 999, background: accent, fontSize: 11, fontWeight: 700 }}>WCAG {level}</span>
      </div>
      <div style={{ marginTop: 10, height: 8, borderRadius: 999, background: "#24143014", overflow: "hidden" }}>
        <div style={{ height: "100%", background: accent, width: fillWidth }} />
      </div>
      {showChecklist && (
        <ul style={{ listStyle: "none", margin: "12px 0 0", padding: 0, display: "flex", flexDirection: "column", gap: 4 }}>
          {items.map((it) => (
            <li key={it.key} style={{ fontSize: 12, color: "#241430aa", opacity: active.includes(it.key) ? 1 : 0.4 }}>&#10003; {it.label}</li>
          ))}
        </ul>
      )}
    </div>
  );
}
